import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.CDh-ZJvO.js";const p=JSON.parse('{"title":"产品简介","description":"","frontmatter":{},"headers":[],"relativePath":"guide/intro.md","filePath":"guide/intro.md","lastUpdated":null}'),i={name:"guide/intro.md"};function n(s,t,l,d,c,g){return a(),o("div",null,[...t[0]||(t[0]=[r(`<h1 id="产品简介" tabindex="-1">产品简介 <a class="header-anchor" href="#产品简介" aria-label="Permalink to &quot;产品简介&quot;">​</a></h1><p><strong>晓雪WEB打印控件</strong>（Xiaoxue WEB Printer）是一套基于 <strong>WebSocket</strong> 的本机 Web 打印解决方案。它在用户电脑上以一个<strong>系统托盘常驻服务</strong>的方式运行，网页通过官方提供的 <code>XiaoxuePrinterSDK</code> 即可与本机打印服务通信，实现真实、稳定、可预览的打印能力。</p><h2 id="它解决什么问题" tabindex="-1">它解决什么问题 <a class="header-anchor" href="#它解决什么问题" aria-label="Permalink to &quot;它解决什么问题&quot;">​</a></h2><p>浏览器原生的 <code>window.print()</code> 存在诸多限制：无法直接选择特定打印机、无法精准控制纸张与边距、不支持静默打印与批量打印、打印预览样式不可控。而传统浏览器 ActiveX 打印插件又在新版 Chrome / Edge 中逐步失去支持。</p><p>晓雪WEB打印控件另辟蹊径：<strong>由本机服务负责&quot;真实打印&quot;，由网页负责&quot;内容与样式&quot;</strong>，两者通过 WebSocket 通信，兼顾了：</p><ul><li><strong>真实打印</strong>：直接调用系统打印服务（Java Print Service），打印结果与本地软件一致；</li><li><strong>样式可控</strong>：text / HTML 经 OpenHTMLtoPDF 渲染为 PDF，纸张、方向、边距、页眉页脚、缩放、字体全部可控；</li><li><strong>浏览器兼容</strong>：任何支持 WebSocket 的现代浏览器（Chrome / Edge / Firefox 等）都可使用，无插件、无驱动安装；</li><li><strong>框架无关</strong>：纯 JS SDK，Vue / React / Angular 等框架均可轻松集成。</li></ul><h2 id="核心组成" tabindex="-1">核心组成 <a class="header-anchor" href="#核心组成" aria-label="Permalink to &quot;核心组成&quot;">​</a></h2><table tabindex="0"><thead><tr><th>组成</th><th>说明</th></tr></thead><tbody><tr><td><strong>本机打印服务</strong></td><td>Java + SWT 编写的托盘程序，监听 <code>ws://127.0.0.1:54321</code>，负责渲染 PDF、输出到打印机、维护打印任务、提供预览窗口与 BarTender 集成</td></tr><tr><td><strong>XiaoxuePrinterSDK</strong></td><td>官方前端 SDK（<code>xiaoxue-printer-sdk.js</code>），封装连接管理与全部打印 API，Promise 化调用</td></tr><tr><td><strong>Demo 示例</strong></td><td>普通打印、打印任务、BarTender、以及 Vue 2 / Vue 3 / React / Angular 集成示例，位于 <code>demo/</code> 目录</td></tr></tbody></table><h2 id="工作原理" tabindex="-1">工作原理 <a class="header-anchor" href="#工作原理" aria-label="Permalink to &quot;工作原理&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  A[浏览器页面] --&gt;|XiaoxuePrinterSDK / WebSocket| B[本机打印服务 127.0.0.1:54321]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  B --&gt;|text / HTML 渲染| C[OpenHTMLtoPDF → PDF]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  C --&gt;|Java Print Service| D[系统打印机]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  B --&gt;|doPreview| E[分页预览窗口]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  B --&gt;|BarTender SDK| F[BarTender 模板]</span></span></code></pre></div><p>一次打印的完整链路：</p><ol><li>页面通过 SDK 调用 <code>doPrint()</code>，将 <strong>打印机、打印样式（style）与打印内容（content）</strong> 以 JSON 形式发送给本机服务；</li><li>服务端 <code>HtmlRenderService</code> 将 text / HTML 与样式组装为 XHTML（<code>@page</code> 控制纸张/边距/页眉页脚，图片自动内嵌）；</li><li>使用 OpenHTMLtoPDF 渲染为 PDF（自动匹配 Windows 注册的宋体、微软雅黑等字体）；</li><li>通过 <code>PrintTaskExecutor</code>（PDFBox <code>PDFPageable</code> + <code>PrinterJob</code>）输出到指定打印机；</li><li>任务完成后自动从任务列表清除，期间任务状态变化会通过 <code>task_list_update</code> 事件推送给页面。</li></ol><h2 id="主要能力一览" tabindex="-1">主要能力一览 <a class="header-anchor" href="#主要能力一览" aria-label="Permalink to &quot;主要能力一览&quot;">​</a></h2><ul><li><strong>打印</strong>：<code>doPrint</code> 支持文本（text）与富 HTML 片段（html）两种内容类型；</li><li><strong>预览</strong>：<code>doPreview</code> 弹出分页预览窗口，支持缩放、翻页、页面设置、导出 PDF / 图片；</li><li><strong>打印机与纸张</strong>：动态获取本机打印机列表、指定打印机的可用纸张；</li><li><strong>任务管理</strong>：任务列表、单个任务状态查询、取消待打印/打印中任务、清除已完成/失败任务；</li><li><strong>BarTender</strong>：获取 BarTender 实例与版本、读取 <code>.btw</code> 模板参数、获取模板图像（支持带参数），配合标签打印；</li><li><strong>授权与常驻</strong>：机器码授权许可、开机自启、系统托盘任务查看。</li></ul><h2 id="适用场景" tabindex="-1">适用场景 <a class="header-anchor" href="#适用场景" aria-label="Permalink to &quot;适用场景&quot;">​</a></h2><ul><li>企业业务系统的<strong>单据、报表、票据、合同</strong>打印；</li><li>需要<strong>静默打印 / 批量打印</strong>的仓储、电商、物流场景；</li><li>需要<strong>套打、标签、条码</strong>的制造业与零售业（结合 BarTender）；</li><li>需要<strong>精准纸张、边距、分页控制</strong>的财务、医疗、政务系统。</li></ul><blockquote><p>下一步：<a href="./features">功能特性</a> 详细了解各项能力，或直接进入<a href="./quick-start">快速开始</a>上手体验。</p></blockquote>`,17)])])}const u=e(i,[["render",n]]);export{p as __pageData,u as default};
